			var uvv := Vector2(local.x + 0.5, local.y + 0.5)
			uv = [uvv.x, uvv.y]
			var a := float(projector.get("opacity", 0.8)) * weight
			opacity = a
			var ink := projector.get("albedo_linear", [0.15,0.03,0.01])
			albedo = [lerp(float(base[0]),float(ink[0]),a), lerp(float(base[1]),float(ink[1]),a), lerp(float(base[2]),float(ink[2]),a)]
	return {"visible":visible, "world_position":[p.x,p.y,p.z] if visible else null, "projector_local_position":[local.x,local.y,local.z] if visible else null, "uv":uv, "opacity":opacity, "normal":[normal.x,normal.y,normal.z] if visible else null, "albedo_linear":albedo if visible else null}

func sample() -> Dictionary:
	var vp := test_input.get("viewport", [128,128])
	var w := int(vp[0]); var h := int(vp[1])
	var pixels: Array = []
