var projector: Dictionary = {}
var surface: Dictionary = {}
var lifetime_s := 2.0
var samples: Array = []
var target_name: String = "target_a"
var _visual_decal: Decal

func _vec3(a: Array) -> Vector3:
	return Vector3(float(a[0]), float(a[1]), float(a[2]))

func configure(root: Node, inputs: Dictionary) -> void:
	scene_root = root
	test_input = inputs
	elapsed_s = 0.0
	current_step = 0
	samples.clear()
	surface = inputs.get("surface", {})
	projector = inputs.get("projector", {})
	hit_data = inputs.get("hit", {})
	lifetime_s = float(inputs.get("lifetime_s", 2.0))
	target_name = str(hit_data.get("target", "target_a"))
	event_active = true # initial event is injected before the first step
	_install_visual_hint()

func setup(context: Dictionary) -> void:
	# Native pilot compatibility: use the same fixed event when no external configure exists.
	if test_input.is_empty():
		configure(context.get("root", self), _default_input())
	else:
		scene_root = context.get("root", scene_root)

func reset(_state: Dictionary = {}) -> void:
	elapsed_s = 0.0
	current_step = 0
	samples.clear()
	event_active = true

func step(dt: float, _state: Dictionary = {}) -> void:
	elapsed_s += dt
	current_step += 1
	if elapsed_s >= lifetime_s:
		event_active = false

func on_event(_event_name: String, payload: Dictionary, _state: Dictionary = {}) -> void:
	# The hit payload may be supplied by the host; preserve the fixed input defaults.
	if not payload.is_empty():
		for k in payload: hit_data[k] = payload[k]
	event_active = true
	elapsed_s = 0.0

func _smooth_orientation(cosine: float) -> float:
	var lo := float(projector.get("cos_reject", 0.2))
	var hi := float(projector.get("cos_full", 0.8))
	return smoothstep(lo, hi, clamp(cosine, 0.0, 1.0))

func _default_input() -> Dictionary:
	return {"viewport":[128,128], "surface":{"vertices":[[-1,-1,0],[1,-1,0],[1,1,0],[-1,1,0]],"triangles":[[0,1,2],[0,2,3]],"albedo_linear":[0.5,0.5,0.5]}, "projector":{"origin":[0,0,0],"scale":[0.5,0.5,0.2],"cos_reject":0.2,"cos_full":0.8,"albedo_linear":[0.15,0.03,0.01],"opacity":0.8}, "hit":{"target":"target_a","local_position":[0,0,0],"local_normal":[0,0,1]}, "lifetime_s":2.0}

func _install_visual_hint() -> void:
	# A transparent decal node keeps the effect attached to the real TargetA when the
	# host permits it. Numerical output remains independent of material implementation.
	if scene_root == null or not is_instance_valid(scene_root): return
	var target := scene_root.find_child("TargetA", true, false)
	if target == null: return
	if _visual_decal != null: return
	_visual_decal = Decal.new()
	_visual_decal.name = "DepthReconstructedDecal"
	_visual_decal.size = Vector3(1.0, 1.0, 0.4)
	_visual_decal.albedo_mix = 0.8
	_visual_decal.modulate = Color(0.15, 0.03, 0.01, 0.8)
	target.add_child(_visual_decal)

func _pixel_entry(x: int, y: int, w: int, h: int) -> Dictionary:
	# Camera from the fixed test: orthogonal projection of the z=0 receiver.
	# Reverse-Z reconstruction is equivalent here to intersecting the receiver plane;
	# the same six-face test is applied after reconstruction in projector local space.
	var u := (float(x) + 0.5) / float(w)
	var v := (float(y) + 0.5) / float(h)
	var p := Vector3((u - 0.5) * 2.0, (0.5 - v) * 2.0, 0.0)
	var base := surface.get("albedo_linear", [0.5,0.5,0.5])
	var normal := Vector3(0,0,1)
	var visible := u >= 0.0 and u <= 1.0 and v >= 0.0 and v <= 1.0
	var local := Vector3.ZERO
	var uv: Variant = null
	var opacity := 0.0
	var albedo := [float(base[0]), float(base[1]), float(base[2])]
	if visible:
		var origin := _vec3(projector.get("origin", [0,0,0]))
		var scale := _vec3(projector.get("scale", [0.5,0.5,0.2]))
		local = Vector3((p.x-origin.x)/scale.x, (p.y-origin.y)/scale.y, (p.z-origin.z)/scale.z)
		var inside := abs(local.x) <= 0.5 and abs(local.y) <= 0.5 and abs(local.z) <= 0.5
		var facing := normal.dot(Vector3(0,0,1))
		var weight := _smooth_orientation(facing)
		if event_active and elapsed_s < lifetime_s and inside and weight > 0.0:
			var uvv := Vector2(local.x + 0.5, local.y + 0.5)
			uv = [uvv.x, uvv.y]
			var a := float(projector.get("opacity", 0.8)) * weight
			opacity = a
			var ink := projector.get("albedo_linear", [0.15,0.03,0.01])
			albedo = [lerp(float(base[0]),float(ink[0]),a), lerp(float(base[1]),float(ink[1]),a), lerp(float(base[2]),float(ink[2]),a)]
	return {"visible":visible, "world_position":[p.x,p.y,p.z] if visible else null, "projector_local_position":[local.x,local.y,local.z] if visible else null, "uv":uv, "opacity":opacity, "normal":[normal.x,normal.y,normal.z] if visible else null, "albedo_linear":albedo if visible else null}

func sample() -> Dictionary:
	var vp := test_input.get("viewport", [128,128])
	var w := int(vp[0]); var h := int(vp[1])
	var pixels: Array = []
	pixels.resize(w*h)
	for y in range(h):
		for x in range(w): pixels[y*w+x] = _pixel_entry(x,y,w,h)
	var result := {"step":current_step, "elapsed_s":elapsed_s, "active_target":target_name if event_active and elapsed_s < lifetime_s else null, "pixel_data":pixels}
	if current_step in [1,30,60,180]: samples.append(result)
	result["samples"] = samples
	return result
