	return {"viewport":[128,128], "surface":{"vertices":[[-1,-1,0],[1,-1,0],[1,1,0],[-1,1,0]],"triangles":[[0,1,2],[0,2,3]],"albedo_linear":[0.5,0.5,0.5]}, "projector":{"origin":[0,0,0],"scale":[0.5,0.5,0.2],"cos_reject":0.2,"cos_full":0.8,"albedo_linear":[0.15,0.03,0.01],"opacity":0.8}, "hit":{"target":"target_a","local_position":[0,0,0],"local_normal":[0,0,1]}, "lifetime_s":2.0}

